import{_ as t,C as n,o,c,j as e,a,E as d,a2 as l}from"./chunks/framework.CdvW4CUT.js";const S=JSON.parse('{"title":"字节码转换器与底层网络协议 (module.sync:processor / management / network)","description":"","frontmatter":{},"headers":[],"relativePath":"26.3/sync/processor-and-network.md","filePath":"26.3/sync/processor-and-network.md"}'),r={name:"26.3/sync/processor-and-network.md"};function h(y,s,p,k,g,E){const i=n("BranchContextCard");return o(),c("div",null,[s[0]||(s[0]=e("h1",{id:"字节码转换器与底层网络协议-module-sync-processor-management-network",tabindex:"-1"},[a("字节码转换器与底层网络协议 ("),e("code",null,"module.sync:processor"),a(" / "),e("code",null,"management"),a(" / "),e("code",null,"network"),a(") "),e("a",{class:"header-anchor",href:"#字节码转换器与底层网络协议-module-sync-processor-management-network","aria-label":'Permalink to "字节码转换器与底层网络协议 (`module.sync:processor` / `management` / `network`)"'},"​")],-1)),d(i,{branch:"26.3"}),s[1]||(s[1]=l('<p>为什么在使用 <code>@Sync</code> 和 <code>@LazySync</code> 时，开发者既不需要在构造器里手写 <code>proxy.setParent(this)</code>，也不需要手动把对象注册到管理器或显式反注册？本篇解析 <code>module.sync:processor</code> 的 ASM 字节码注入原理、<code>LazySyncManager</code> 的弱引用快照防回环机制以及配置阶段 ID 映射表同步流程。</p><hr><h2 id="一、-编译期索引与加载期-asm-字节码注入-module-sync-processor" tabindex="-1">一、 编译期索引与加载期 ASM 字节码注入 (<code>module.sync:processor</code>) <a class="header-anchor" href="#一、-编译期索引与加载期-asm-字节码注入-module-sync-processor" aria-label="Permalink to &quot;一、 编译期索引与加载期 ASM 字节码注入 (`module.sync:processor`)&quot;">​</a></h2><p><code>SyncClassProcessor</code> 实现了 NeoForge 的 <code>net.neoforged.neoforgespi.transformation.ClassProcessor</code> 接口（处理器名称 <code>anvillib_sync:processor</code>），在游戏启动类加载阶段对包含 <code>@Sync</code> 或 <code>@LazySync</code> 的类执行无感字节码改写：</p><h3 id="_1-syncbytecodeinjector-针对-sync-类的注入" tabindex="-1">1. <code>SyncBytecodeInjector</code>（针对 <code>@Sync</code> 类的注入） <a class="header-anchor" href="#_1-syncbytecodeinjector-针对-sync-类的注入" aria-label="Permalink to &quot;1. `SyncBytecodeInjector`（针对 `@Sync` 类的注入）&quot;">​</a></h3><p>当类上标注了 <code>@Sync</code> 时，扫描类中所有描述符为 <code>SyncProxy</code> 且带有 <code>ACC_FINAL</code> 的字段：</p><ul><li><strong>对于实例 <code>final SyncProxy</code> 字段</strong>：在类的每一个构造器 <code>&lt;init&gt;</code> 的所有 <code>RETURN</code> 指令前注入：<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setParent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFieldName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDirection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.XXX); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 仅当字段自身未显式指定方向时生效</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>对于静态 <code>static final SyncProxy</code> 字段</strong>：在类的 <code>&lt;clinit&gt;</code>（若不存在则自动创建）的所有 <code>RETURN</code> 指令前注入：<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (Owner.field </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setParent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Owner.class);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFieldName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDirection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.XXX);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ul><h3 id="_2-lazysyncbytecodeinjector-针对含-lazysync-字段的类的注入" tabindex="-1">2. <code>LazySyncBytecodeInjector</code>（针对含 <code>@LazySync</code> 字段的类的注入） <a class="header-anchor" href="#_2-lazysyncbytecodeinjector-针对含-lazysync-字段的类的注入" aria-label="Permalink to &quot;2. `LazySyncBytecodeInjector`（针对含 `@LazySync` 字段的类的注入）&quot;">​</a></h3><p>当类中存在任何带有 <code>@LazySync</code> 注解的字段时：</p><ul><li><strong>若存在实例 <code>@LazySync</code> 字段</strong>：在每个构造器 <code>&lt;init&gt;</code> 的 <code>RETURN</code> 前注入：<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AnvilLibSync.LAZY_SYNC_MANAGER.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">track</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div></li><li><strong>若存在静态 <code>@LazySync</code> 字段</strong>：在 <code>&lt;clinit&gt;</code> 的 <code>RETURN</code> 前注入：<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AnvilLibSync.LAZY_SYNC_MANAGER.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trackStatic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Owner.class);</span></span></code></pre></div></li></ul><hr><h2 id="二、-lazysyncmanager-弱引用跟踪与防回环设计" tabindex="-1">二、 <code>LazySyncManager</code> 弱引用跟踪与防回环设计 <a class="header-anchor" href="#二、-lazysyncmanager-弱引用跟踪与防回环设计" aria-label="Permalink to &quot;二、 `LazySyncManager` 弱引用跟踪与防回环设计&quot;">​</a></h2><ol><li><strong>自动 GC 回收（无需手动 <code>untrack</code>）</strong>： <code>LazySyncManager</code> 内部存储实例集合 <code>instances</code> 和快照表 <code>snapshots</code> 时，均使用了 Guava 的 <strong><code>new MapMaker().weakKeys()</code>（弱引用 + 身份相等 <code>==</code> 映射）</strong>。当一个 <code>BlockEntity</code> 或 <code>Entity</code> 从世界卸载并失去外部强引用后，JVM 垃圾回收器会自动将其从 <code>LazySyncManager</code> 中清理掉，绝不会造成内存泄漏。</li><li><strong>首次基线建立与回环抑制</strong>： <ul><li>当对象构造后第一次被 <code>scanTarget</code> 扫描时，仅将各字段初始编码字节存入 <code>snapshots</code> 建立基线，不会发送初始包；</li><li>当对端收到 <code>LazySyncPayload</code> 并调用 <code>applyGrouped</code> 写回字段值时，会<strong>立即用写回的新值重新编码更新本端 <code>snapshots</code></strong>，从而保证下一 Tick 扫描时不会把对端刚刚同步过来的值误判为本端产生的新变更而再次发包回去（彻底杜绝双向同步死循环）。</li><li>注意：对于 <code>C2S</code> 或 <code>BOTH</code> 方向的 <code>SyncProxy</code> / <code>@LazySync</code>，当<strong>服务端</strong>收到某客户端发来的更新时，服务端在写回本地状态后会自动将该变更广播给追踪该对象的其他客户端。</li></ul></li></ol><hr><h2 id="三、-配置阶段字段-id-字典同步-syncconfigmanager" tabindex="-1">三、 配置阶段字段 ID 字典同步 (<code>SyncConfigManager</code>) <a class="header-anchor" href="#三、-配置阶段字段-id-字典同步-syncconfigmanager" aria-label="Permalink to &quot;三、 配置阶段字段 ID 字典同步 (`SyncConfigManager`)&quot;">​</a></h2><p>为了不在每次字段同步包中传输冗长的 <code>&quot;com.example.HeaterBlockEntity#temperature&quot;</code> 字符串：</p><ol><li>在 <code>FMLCommonSetupEvent</code> 阶段，<code>SyncConfigManager.compileContent()</code> 扫描所有模组的 <code>@Sync</code> 类（提取其中的 <code>final SyncProxy</code> 字段）和 <code>@LazySync</code> 字段，为每个 <code>&quot;ClassName#fieldName&quot;</code> 分配一个紧凑的整数 <code>configId</code>；</li><li>在玩家连接服务器的 <code>RegisterConfigurationTasksEvent</code> 配置阶段，<code>AnvilLibSync.SyncConfig</code>（<code>anvillib_sync:sync_config</code>）向客户端发送 <code>SyncConfigurationPayload</code>，将服务端的 <code>Map&lt;Integer, String&gt;</code> 字段字典同步给客户端，客户端采纳后回复 <code>SyncConfigurationFinishPayload</code>。</li></ol><hr><h2 id="四、-底层管理与网络类参考表-apistatus-internal" tabindex="-1">四、 底层管理与网络类参考表 (<code>@ApiStatus.Internal</code>) <a class="header-anchor" href="#四、-底层管理与网络类参考表-apistatus-internal" aria-label="Permalink to &quot;四、 底层管理与网络类参考表 (`@ApiStatus.Internal`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">包 / 类名</th><th style="text-align:left;">核心职责</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AnvilLibSync</code></td><td style="text-align:left;">模块主类，持有 <code>SYNC_MANAGER</code>、<code>SYNC_CONFIG_MANAGER</code> 与 <code>LAZY_SYNC_MANAGER</code> 单例。</td></tr><tr><td style="text-align:left;"><code>SyncManager</code></td><td style="text-align:left;">管理 <code>SyncRegisterEntry</code> 宿主映射并处理 <code>SyncProxy#setValue</code> 的即时发包。</td></tr><tr><td style="text-align:left;"><code>LazySyncManager</code></td><td style="text-align:left;">管理 <code>@LazySync</code> 实例/静态类的弱引用集合、字节快照对比与分组批量发包/写回。</td></tr><tr><td style="text-align:left;"><code>SyncConfigManager</code></td><td style="text-align:left;">扫描并维护 <code>&quot;ClassName#fieldName&quot; &lt;-&gt; int</code> 整数索引映射表。</td></tr><tr><td style="text-align:left;"><code>SideUtil</code></td><td style="text-align:left;">提供双端 <code>RegistryAccess</code> 获取、内置 <code>entityFinder</code> / <code>blockEntityFinder</code> 以及按区块（<code>sendToPlayersTrackingChunk</code>）/ 按实体（<code>sendToPlayersTrackingEntity</code>）/ 按维度（<code>sendToPlayersInDimension</code>）智能路由的 <code>serverSend</code> 方法。</td></tr><tr><td style="text-align:left;"><code>SyncPayload</code> / <code>LazySyncPayload</code></td><td style="text-align:left;">即时单字段同步数据包（<code>anvillib_sync:sync</code>）与惰性多字段分组同步数据包（<code>anvillib_sync:lazy_sync</code>）。</td></tr><tr><td style="text-align:left;"><code>SyncConfigurationPayload</code> / <code>SyncConfigurationFinishPayload</code></td><td style="text-align:left;">配置阶段字段 ID 映射表同步包与确认包。</td></tr></tbody></table>',20))])}const C=t(r,[["render",h]]);export{S as __pageData,C as default};
